import {defaults,demoData,demoMinuteData,parseCSV,backtest,compareParameters,compareManagement,managementNames,orderFees,detectTimeframe,resampleData,dailyGroups,periodLabel} from './engine.mjs';
import {auditBundle} from './quality.mjs';
import {boardNames} from './rules.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const names={swing:'大波段趋势策略',ma:'双均线策略',macd:'MACD 动量策略',rsi:'RSI 超卖反弹',boll:'布林带均值回归'};
const descriptions={swing:'已完成日线确认趋势与突破，执行周期均线确认入场；日线转弱或 ATR 跟踪止损离场。',ma:'前根短均线高于长均线时持仓，低于时离场；周期以 K 线根数计。',macd:'前根 DIF 高于信号线时持仓，低于时离场。',rsi:'前根 RSI 低于买入阈值入场，高于卖出阈值离场。',boll:'前根收盘低于布林下轨入场，回到中轨时离场。'};
const demo=demoMinuteData();
let data=demo,dataName='演示标的 · 合成 5 分钟',source='demo',strategy='swing';
let activeSnapshotId=null,importedSnapshotId=null;
let activeBundle=null,importedBundle=null,qualityReport=null,warehouseEntries=[],warehouseCursor=null;
let result,reportData,page=0,chartMode='nav',activeTab='trades',dirty=false,toastTimer,importedData,importedName;
let history=[];try{const h=JSON.parse(localStorage.getItem('qingheng-history')||'[]');if(Array.isArray(h))history=h.filter(x=>x&&x.config&&x.metrics&&x.period).slice(0,20);}catch{}
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const pct=(v,signed=false)=>Number.isFinite(v)?(signed&&v>0?'+':'')+num(v*100)+'%':'—';
const cls=v=>!Number.isFinite(v)||v===0?'neutral':v>0?'positive':'negative';
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
let requestId=0;const requests=new Map();let worker;
try{worker=new Worker('./worker.js',{type:'module'});worker.onmessage=({data:{id,result,error}})=>{const pending=requests.get(id);if(!pending)return;requests.delete(id);error?pending.reject(Error(error)):pending.resolve(result);};worker.onerror=()=>{for(const p of requests.values())p.reject(Error('回测计算进程加载失败，请刷新后重试。'));requests.clear();worker.terminate();worker=null;};}catch{}
function compute(type,data,config){if(!worker)return Promise.resolve().then(()=>type==='compare'?compareParameters(data,config):type==='management'?compareManagement(data,config):backtest(data,config));return new Promise((resolve,reject)=>{const id=++requestId;requests.set(id,{resolve,reject});worker.postMessage({id,type,data,config});});}
function config(){const o={...defaults,strategy,snapshotId:activeSnapshotId};for(const[k,v]of new FormData($('#config')))o[k]=typeof defaults[k]==='number'?Number(v):v;o.dataMode=source==='demo'?'demo':($('#data-mode').value||'formal');return o;}
function setConfig(c){const loaded={...defaults,...c,timeframe:c.timeframe||'1d',dataMode:c.dataMode==='demo'||!c.dataMode?'formal':c.dataMode};for(const[k,v]of Object.entries(loaded)){const el=$('#config').elements.namedItem(k);if(el)el.value=v;}selectStrategy(loaded.strategy);markDirty();}
function markDirty(){updateFeePreview();dirty=true;$('#config-status').textContent='参数已更改 · 点击运行回测更新结果';$('#config-status').className='config-status dirty';}
function selectStrategy(s){strategy=s;$$('[data-strategy]').forEach(b=>b.classList.toggle('active',b.dataset.strategy===s));$$('.strategy-params').forEach(p=>p.hidden=!(p.id==='params-'+s||p.id==='params-ma'&&s==='swing'));$('#strategy-desc').textContent=descriptions[s];$('#optimizer-title').textContent=s==='swing'?'大波段参数验证':'双均线参数验证';markDirty();}
function showView(v){$$('.view').forEach(p=>p.hidden=p.id!=='view-'+v);$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#breadcrumb').textContent={backtest:'策略回测',data:'行情数据',history:'本机回测记录',method:'回测规则'}[v];if(v==='history')renderHistory();if(v==='data'){renderData();renderQuality();refreshWarehouse();}if(v==='backtest')requestAnimationFrame(renderChart);window.scrollTo({top:0,behavior:'instant'});}
function saveHistory(r,runName,runSource){history.unshift({id:Date.now(),at:new Date().toISOString(),source:runSource,dataName:runName,config:r.config,metrics:r.metrics,period:r.period,engineVersion:r.audit.engineVersion});history=history.slice(0,20);try{localStorage.setItem('qingheng-history',JSON.stringify(history));}catch{toast('浏览器存储不可用，本次记录仅保留在当前页面。');}}
async function run(save=true){const runData=activeBundle??data,runName=dataName,runSource=source,c=config();$('#run').disabled=true;$('#run').textContent='正在回测…';$('#config-status').textContent='正在计算已完成 K 线与逐根成交…';
  try{if(source==='import'&&!activeBundle&&c.dataMode!=='exploration')throw Error('普通 CSV 缺少历史 ST、公司行动及覆盖证明；正式研究需要完整 JSON 数据包。可切换 CSV 探索。');const r=await compute('backtest',runData,c);result={...r,dataName:runName,source:runSource};reportData=runData;page=0;dirty=false;$('#config-status').textContent=`回测完成 · ${r.period.tradingDays} 个交易日 / ${num(r.period.bars,0)} 根 K 线`;$('#config-status').className='config-status';$('#optimizer-results').innerHTML='';$('#management-results').innerHTML='';renderResults();if(save)saveHistory(r,runName,runSource);return true;}
  catch(e){$('#config-status').textContent=e.message;$('#config-status').className='config-status error';toast(e.message);return false;}
  finally{$('#run').disabled=false;$('#run').innerHTML='<span>▷</span> 运行回测';}
}
function renderResults(){const m=result.metrics;$('#result-title').textContent=names[result.config.strategy]+(result.config.strategy==='swing'?' · '+managementNames[result.config.management]:'');$('#result-source').textContent=(result.source==='demo'?'演示 · ':result.source==='bundle'?'已校验数据包 · ':'探索导入 · ')+periodLabel(result.config.timeframe);$('#result-period').textContent=result.period.from.slice(0,10)+' — '+result.period.to.slice(0,10);$('#chart-range').textContent=result.period.from.slice(0,10)+' 至 '+result.period.to.slice(0,10);$('#chart-days').textContent=`${result.period.tradingDays} 个交易日 · ${num(result.period.bars,0)} 根`;
  const list=[['累计收益',m.total,'期末资产 ¥ '+num(m.equity)],['年化收益',m.annual,'按交易日计数折算'],['最大回撤',m.maxdd,'覆盖全部执行周期净值'],['夏普比率',m.sharpe,'使用日末收益 · 无风险利率 0']];
  $('#metrics').innerHTML=list.map(([label,value,detail],i)=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value ${i<3?cls(value):'neutral'}">${i<3?(Number.isFinite(value)?`${value>0&&i<2?'+':''}${num(value*100)}<small>%</small>`:'—'):num(value)}</div><div class="metric-detail">${detail}</div></div>`).join('');
  $('#causal-status').textContent=`时序校验通过 · ${num(result.audit.decisions,0)} 次决策 · 仅已完成 K 线 / 次根开盘 / 跨日 T+1`+(result.warnings.length?'。'+result.warnings.join(' '):'');$('#causal-status').classList.toggle('warning',result.warnings.length>0);
  $('#trade-count').textContent=result.trades.length;renderTrades();renderStats();renderAudit();renderChart();
}
function renderTrades(){const rows=result.trades.slice().reverse(),pages=Math.max(1,Math.ceil(rows.length/8));page=Math.max(0,Math.min(page,pages-1));$('#trades-body').innerHTML=rows.length?rows.slice(page*8,page*8+8).map(t=>`<tr><td>${t.date}</td><td><span class="side-pill ${t.side==='买入'?'buy':'sell'}">${t.side}</span></td><td>${num(t.price,3)}</td><td>${num(t.quantity,0)}</td><td><span title="佣金 ${num(t.feeBreakdown?.commission)} / 印花税 ${num(t.feeBreakdown?.stamp)} / 经手 ${num(t.feeBreakdown?.handling)} / 证管 ${num(t.feeBreakdown?.regulatory)} / 过户 ${num(t.feeBreakdown?.transfer)}">${num(t.fee)}</span></td><td class="${cls(t.pnl)}">${t.pnl===null?'—':num(t.pnl)}</td><td>${t.reason}</td></tr>`).join(''):'<tr><td colspan="7" class="empty">该区间没有可成交信号。大波段策略需要完整日线趋势与突破，不要求每天交易。</td></tr>';$('#trade-summary').textContent=`共 ${rows.length} 笔成交 · ${result.closed.length} 笔已平仓`;$('#page-label').textContent=(page+1)+' / '+pages;$('#prev-page').disabled=page===0;$('#next-page').disabled=page>=pages-1;}
function renderStats(){const m=result.metrics;const rows=[['标的买入持有收益',pct(m.benchmark)],['策略相对标的收益',pct(m.excess,true)],['已平仓胜率',pct(m.winrate)],['已平仓盈亏比',num(m.profitFactor)],['日收益年化波动率',pct(m.volatility)],['平均持仓 / 交易日',num(m.averageHoldingDays,1)],['持仓 K 线占比',pct(m.exposure)],['累计交易费用','¥ '+num(m.fees)],['停牌 / 限价未成交',m.blocked+' 次尝试'],['因 T+1 暂不可卖',m.t1Blocked+' 次尝试'],['期末持仓',num(m.quantity,0)+' 股'],['期末现金','¥ '+num(m.cash)],['已平仓交易',result.closed.length+' 笔'],['样本交易日',result.period.tradingDays+' 日'],['已平仓样本',m.closedTrades+' 笔'],['胜率 95% Wilson 下界',pct(m.wilsonLower)],['每笔已平仓平均盈亏','¥ '+num(m.expectancy)],['最差已平仓收益',pct(m.worstTrade)],['当前未闭合波段盈亏','¥ '+num(m.openUnrealized)],['趋势加仓',m.adds+' 次'],['已配对 T 净价差','¥ '+num(m.tNet)],['已配对 / 未配对 T',m.tPaired+' / '+m.tUnmatched+' 笔'],['T 相关成交费用','¥ '+num(m.tFees)],...Object.entries(result.feeTotals).map(([k,v])=>[({commission:'佣金',stamp:'印花税',handling:'经手费',regulatory:'证管费',transfer:'过户费'})[k]+'累计','¥ '+num(v)])];$('#tab-stats').innerHTML='<div class="stats-grid">'+rows.map(([k,v])=>`<div class="stat-row"><span>${k}</span><strong>${v}</strong></div>`).join('')+'</div><p class="stats-note">年化与夏普基于交易日，回撤覆盖全部分钟点。盈亏比只统计已平仓盈利总额 / 亏损总额；没有亏损交易时不显示。期末不强制卖出。T 净价差只统计同股数已配对两腿，已扣各自费用，已包含在总净值中，不能再相加。未配对库存按实际持仓估值；当前未闭合波段盈亏包含该波段全部已实现价差和权益。T 价差不等于对底仓方案的超额收益。</p>'+renderTPairs();}
function renderAudit(){const a=result.audit;$('#tab-audit').innerHTML=`<div class="audit-summary"><strong>信号时间 ≤ 开盘执行时间：${a.timingViolations===0?'通过':'失败'}</strong><br>成交不读取当根尚未完成的高 / 低 / 收 / 成交量。日线只在 15:00 后可见；突破窗口排除信号当日。下表显示最近 10 笔成交，可从导出报告复核全部时序。</div><div class="table-wrap audit-table"><table><thead><tr><th>方向</th><th>执行周期信号收盘</th><th>使用的日线收盘</th><th>估算开盘执行</th></tr></thead><tbody>${result.trades.length?result.trades.slice(-10).reverse().map(t=>`<tr><td>${t.side}</td><td>${t.signalTime}</td><td>${t.dailySignalTime||'该策略未使用日线过滤'}</td><td>${t.executionTime}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">本区间无成交；所有决策仍进行时间顺序检查。</td></tr>'}</tbody></table></div><p class="stats-note" style="padding-top:16px">历史 ST 入场剔除 ${a.stExcluded} 次。公司行动账本 ${result.corporateEvents?.length??0} 条；详见报告。${a.qualityReport?'完整数据准入：'+a.qualityReport.label:'当前数据没有独立完整性证明'}。时序校验不能验证外部 CSV 的真实性与当时可得性。复权序列、限价与停牌标记也应按当时已知口径提供。零延迟开盘执行为研究假设，不模拟实际委托延迟与排队。</p>`;}
function renderChart(){if(!result||$('#view-backtest').hidden)return;const el=$('#chart'),w=Math.max(300,el.clientWidth-24),h=el.clientHeight,pad={l:53,r:14,t:16,b:33},pw=w-pad.l-pad.r,ph=h-pad.t-pad.b;
  const first={date:'起始资金',nav:1,benchmark:1,drawdown:0,equity:result.config.capital},points=[first,...result.curve],step=Math.ceil(points.length/650);
  const sample=[];let lo=Infinity,hi=-Infinity;
  points.forEach((p,i)=>{if(i%step===0||i===points.length-1)sample.push({p,i});for(const v of chartMode==='nav'?[p.nav,p.benchmark]:[p.drawdown]){lo=Math.min(lo,v);hi=Math.max(hi,v);}});
  const field=chartMode==='nav'?'nav':'drawdown',span=hi-lo||.1;lo-=span*.12;hi+=span*.12;if(chartMode==='drawdown')hi=0;
  const y=v=>pad.t+(hi-v)/(hi-lo)*ph,x=i=>pad.l+i/(points.length-1)*pw,path=key=>sample.map(({p,i},n)=>`${n?'L':'M'}${x(i).toFixed(2)},${y(p[key]).toFixed(2)}`).join(' ');
  let svg=`<svg viewBox="0 0 ${w} ${h}" aria-hidden="true"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#0e887c" stop-opacity=".13"/><stop offset="100%" stop-color="#0e887c" stop-opacity=".005"/></linearGradient></defs>`;
  for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4,yy=y(v);svg+=`<line x1="${pad.l}" y1="${yy}" x2="${w-pad.r}" y2="${yy}" stroke="#eaf0f4" stroke-dasharray="3 4"/><text x="${pad.l-10}" y="${yy+4}" text-anchor="end">${chartMode==='nav'?num(v):num(v*100,1)+'%'}</text>`;}
  svg+=`<path d="${path(field)} L ${x(points.length-1)},${y(chartMode==='nav'?lo:0)} L ${x(0)},${y(chartMode==='nav'?lo:0)} Z" fill="url(#area)"/>`;
  if(chartMode==='nav')svg+=`<path d="${path('benchmark')}" fill="none" stroke="#a9b7c9" stroke-width="1.7" stroke-dasharray="5 3"/>`;
  svg+=`<path d="${path(field)}" fill="none" stroke="#0e887c" stroke-width="2.3" stroke-linejoin="round"/>`;
  for(let i=0;i<5;i++){const index=Math.round((points.length-2)*i/4)+1,label=result.period.tradingDays===1?points[index].date.slice(11):points[index].date.slice(0,7);svg+=`<text x="${x(index)}" y="${h-9}" text-anchor="${i===0?'start':i===4?'end':'middle'}">${label}</text>`;}
  svg+=`<line id="crosshair" y1="${pad.t}" y2="${h-pad.b}" stroke="#87bdb5" stroke-dasharray="4" visibility="hidden"/><rect x="${pad.l}" y="${pad.t}" width="${pw}" height="${ph}" fill="transparent"/></svg>`;el.innerHTML=svg;
  $('#benchmark-legend').hidden=chartMode!=='nav';$('#chart-unit').textContent=chartMode==='nav'?'起始净值 1.000':'相对历史峰值';$('#chart-subtitle').textContent=chartMode==='nav'?'执行周期净值 · 已扣除交易成本':'执行周期回撤 · 从初始资金计算';
  el.onpointermove=e=>{const box=el.querySelector('svg').getBoundingClientRect(),local=(e.clientX-box.left)*w/box.width;if(local<pad.l||local>w-pad.r){hideTip();return;}const i=Math.max(0,Math.min(points.length-1,Math.round((local-pad.l)/pw*(points.length-1)))),r=points[i];const cross=$('#crosshair');cross.setAttribute('x1',x(i));cross.setAttribute('x2',x(i));cross.setAttribute('visibility','visible');$('#chart-tooltip').innerHTML=`<b>${r.date}</b><br>策略净值 ${num(r.nav,4)}<br>${chartMode==='nav'?'标的净值 '+num(r.benchmark,4):'回撤 '+pct(r.drawdown)}<br>资产 ¥ ${num(r.equity)}`;$('#chart-tooltip').hidden=false;};el.onpointerleave=hideTip;
}
function hideTip(){$('#chart-tooltip').hidden=true;$('#crosshair')?.setAttribute('visibility','hidden');}
function renderData(){const tf=detectTimeframe(data);$('#data-title').textContent=dataName;$('#data-count').textContent=periodLabel(tf)+' · '+num(data.length,0)+' 根';$('#data-body').innerHTML=data.slice(-10).reverse().map(r=>`<tr><td>${r.date}</td><td>${num(r.open)}</td><td>${num(r.high)}</td><td>${num(r.low)}</td><td>${num(r.close)}</td><td>${num(r.volume,0)}</td></tr>`).join('');$('#data-range').textContent=`原始时间区间 ${data[0].date} — ${data.at(-1).date} · 显示最近 10 根 K 线 · 分钟时间为收盘时间`;}
function renderHistory(){if(!history.length){$('#history-body').innerHTML='<div class="empty">暂无本机回测记录。运行一次回测后，参数与指标会出现在这里。</div>';return;}$('#history-body').innerHTML='<table><thead><tr><th>运行时间</th><th>标的 / 策略 / 周期</th><th>累计收益</th><th>最大回撤</th><th>回测区间</th><th>操作</th></tr></thead><tbody>'+history.map((r,i)=>`<tr><td>${esc(new Date(r.at).toLocaleString('zh-CN',{hour12:false}))}</td><td>${esc(r.dataName)}<br>${esc(names[r.config.strategy]||r.config.strategy)} · ${periodLabel(r.config.timeframe||'1d')}${r.engineVersion?'':' · 旧版口径'}</td><td class="${cls(r.metrics.total)}">${pct(r.metrics.total,true)}</td><td class="negative">${pct(r.metrics.maxdd)}</td><td>${esc(r.period.from)} — ${esc(r.period.to)}</td><td><button class="load-params" data-history="${i}">载入参数</button></td></tr>`).join('')+'</tbody></table>';$$('[data-history]').forEach(b=>b.onclick=()=>{setConfig(history[Number(b.dataset.history)].config);showView('backtest');toast('已载入参数；确认标的后按新版成交口径运行。');});}
function download(name,content,type='text/csv;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportReport(){if(!result)return;download('青衡回测报告-'+result.period.to.slice(0,10)+'.json',JSON.stringify({...result,exportedAt:new Date().toISOString(),methodology:{timezone:'Asia/Shanghai',timestampConvention:'bar-close',signal:'completed previous bar -> next bar open; daily available at 15:00',execution:'open plus adverse slippage, known limits only; no current high/low/close/volume',calendar:result.source==='demo'?'synthetic weekdays':result.source==='bundle'?'independent provider calendar':'unverified CSV sessions',statistics:'252 trading days; Sharpe from daily equity returns; drawdown from all execution bars',fees:result.config.taxMode==='historical'?'historical stamp/transfer plus separate commission/handling/regulatory':'five separate per-order user fees; commission minimum only',dividends:result.corporateEvents??[],benchmark:'raw-price buy and hold with same entitlement ledger; whole shares; no fees',openPositions:'mark to last close, not liquidated'},data:reportData},null,2),'application/json');toast('已导出参数、原始行情、净值、成交与信号时序。');}
function updateSource(){$('#source-notice').textContent=source==='demo'?'当前为合成分钟演示行情，非真实股票数据。正式研究需导入含历史 ST 与公司行动的完整数据包。':activeBundle?`当前数据包：${dataName} · ${qualityReport.label}。${qualityReport.status==='blocked'?'请补齐缺失资料，正式回测已阻止。':'按历史状态过滤 ST，原始价成交与权益账本核算。'}`:`当前标的：${dataName} · ${periodLabel(detectTimeframe(data))} · ${num(data.length,0)} 根。请运行回测更新结果。`;}
function setImportPeriod(){const native=detectTimeframe(data);$('#timeframe').value=native==='5m'?'15m':native;const groups=dailyGroups(data),c=config();let pivot;
  if(c.strategy==='swing'){const full=groups.filter(g=>g.complete);const count=Math.max(c.dailySlow,c.breakout+1,c.exitPeriod,c.atrPeriod);pivot=full[Math.min(count,Math.max(0,full.length-2))]?.date;}
  else pivot=data[Math.min(Math.max(35,c.slow),data.length-2)].date.slice(0,10);
  $('#config').elements.from.value=pivot||groups[0].date;$('#config').elements.to.value=data.at(-1).date.slice(0,10);
}
$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$$('[data-strategy]').forEach(b=>b.onclick=()=>selectStrategy(b.dataset.strategy));$('#config').addEventListener('input',markDirty);$('#config').addEventListener('change',markDirty);$('#config').onsubmit=e=>{e.preventDefault();run();};
$$('[data-chart]').forEach(b=>b.onclick=()=>{chartMode=b.dataset.chart;$$('[data-chart]').forEach(x=>x.classList.toggle('active',x===b));renderChart();});
