$('#optimize').onclick=async()=>{const btn=$('#optimize'),c=config(),runData=activeBundle??data,runName=dataName;btn.disabled=true;btn.textContent='正在训练 / 验证…';try{if(source==='import'&&!activeBundle&&c.dataMode!=='exploration')throw Error('正式参数研究需要含历史成分、ST与公司行动的完整数据包。');const comparison=await compute('compare',runData,c);const {rows}=comparison;const label=r=>c.strategy==='swing'?`${r.config.dailySlow} 日 / ${r.config.atrMult} ATR`:`${r.config.fast} / ${r.config.slow} 根`;$('#optimizer-results').innerHTML=`<div class="validation-split">${esc(runName)} · ${periodLabel(c.timeframe)}<br>训练目标：${c.objective==='quality'?'胜率保守估计 + 收益 / 回撤':'仅收益对照'} · 达到准入 ${comparison.qualified} 组<br>训练 ${comparison.trainFrom} — ${comparison.trainTo}<br>验证 ${comparison.validationFrom} — ${comparison.validationTo} · 验证段从空仓重启，仅用历史预热</div><div class="table-wrap"><table><thead><tr><th>${c.strategy==='swing'?'日线长均线 / ATR':'执行周期均线'}</th><th>训练收益 / 成交数</th><th>训练胜率下界</th><th>验证收益 / 胜率</th><th>验证回撤</th><th>操作</th></tr></thead><tbody>${rows.map((r,i)=>r.error?`<tr><td>${label(r)}</td><td colspan="5">${esc(r.error)}</td></tr>`:`<tr class="${i===0&&r.quality?.eligible?'picked':''}"><td>${label(r)}${i===0&&r.quality?.eligible?' · 训练优选':' · '+r.quality.reason}</td><td class="${cls(r.training.total)}">${pct(r.training.total,true)} / ${r.training.closedTrades} 笔</td><td>${pct(r.training.wilsonLower)}</td><td class="${cls(r.validation.total)}">${pct(r.validation.total,true)} / ${pct(r.validation.winrate)}</td><td class="negative">${pct(r.validation.maxdd)}</td><td><button class="load-params" data-opt="${i}">回测验证段</button></td></tr>`).join('')}</tbody></table></div><p class="stats-note" style="padding-top:16px">评分和准入只用训练段，未用验证结果选参。胜率下界为95% Wilson统计下界，假设样本独立；交易相关性会削弱该估计。不能保证每笔盈利；样本不足或标准未达时不推荐。验证不是未来保证；反复据此调参后需换新的验证区间。</p>`;$$('[data-opt]').forEach(b=>b.onclick=()=>{setConfig({...rows[Number(b.dataset.opt)].config,from:comparison.validationFrom,to:comparison.validationTo});toast('已载入参数与独立验证区间，点击运行回测。');});}catch(e){toast(e.message);}finally{btn.disabled=false;btn.textContent='运行 9 组训练 / 验证';}};
$('#clear-history').onclick=()=>{history=[];try{localStorage.removeItem('qingheng-history');}catch{}renderHistory();toast('本机回测记录已清空。');};
async function api(path,options={}){const r=await fetch(path,options);let v;try{if(path.startsWith('/api/data/bundle?id=')){const bytes=await r.arrayBuffer(),expected=new URL(path,location.origin).searchParams.get('id'),digest=await crypto.subtle.digest('SHA-256',bytes),actual=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');if(r.ok&&actual!==expected)throw Error('快照 SHA-256 不一致，已拒绝载入。');v=JSON.parse(new TextDecoder().decode(bytes));}else v=await r.json();}catch(e){if(e.message.includes('SHA-256'))throw e;throw Error('行情仓库接口暂不可用，请保留本地文件后重试。');}if(!r.ok)throw Error(v.error||'仓库请求失败');return v;}
function renderQuality(){
  const el=$('#quality-status');if(!activeBundle){el.innerHTML=source==='demo'?'<strong>合成演示 · 不属于真实行情验证</strong><p class="help">演示日历只排除周末，仅用于体验策略与成交流程。</p>':'<strong class="quality-blocked">CSV 完整性未验证</strong><p class="help">无法核对整日缺失、历史 ST、公司行动和因子。当时是否沪深 300 成分股也需独立资料。只可做探索研究。</p>';return;}
  const q=qualityReport,m=activeBundle.metadata;el.innerHTML=`<div class="quality-summary"><span class="quality-${q.status}">${esc(q.label)}</span><span>${esc(boardNames[m.board]||'板块缺失')} · ${esc(m.symbol)}</span><span>${q.completeSessions} / ${q.sessions} 个完整交易日</span><span>${q.suspendedSessions} 个已确认停牌日</span></div><p class="help">请求含预热：${esc(q.requested.from)} — ${esc(q.requested.to)}<br>实际返回：${esc(q.actual.from||'无')} — ${esc(q.actual.to||'无')} · ${num(q.actual.bars,0)} 根</p>${q.issues.length?'<ul class="quality-issues">'+q.issues.map(x=>`<li><strong>${esc(x.message)}（${x.count}）</strong>${x.samples.length?'<small>'+esc(x.samples.join('、'))+'</small>':''}</li>`).join('')+'</ul>':'<p>逐日网格、历史状态、独立日线与除权因子链校验通过。</p>'}<p class="help">${esc(q.warning)}</p>`;
}
async function loadBundle(b,name,persist=false,snapshotId=null){
  activeSnapshotId=snapshotId;importedSnapshotId=snapshotId;const q=auditBundle(b);if(!b.bars.length)throw Error('数据包没有可预览行情。');activeBundle=b;importedBundle=b;qualityReport=q;data=b.bars;importedData=data;dataName=b.metadata.symbol+' · '+(b.metadata.name||name);importedName=dataName;source='bundle';let opt=$('#dataset option[value="import"]');if(!opt){opt=document.createElement('option');opt.value='import';$('#dataset').append(opt);}opt.textContent=dataName+' · 数据包';$('#dataset').value='import';$('#board').value=b.metadata.board||'main';$('#board').disabled=true;setImportPeriod();updateSource();renderData();renderQuality();markDirty();$('#import-status').textContent=q.label+'；'+data.length+' 根行情。';
  if(persist){try{const saved=await api('/api/data/ingest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});activeSnapshotId=saved.id;importedSnapshotId=saved.id;$('#import-status').textContent='已持久保存 · 快照 '+saved.id.slice(0,12)+' · '+q.label;await refreshWarehouse();}catch(e){$('#import-status').textContent=e.message+' 当前文件仍在页面内，请保留本地副本。';toast(e.message);}}
}
async function refreshWarehouse(cursor=null){
  $('#warehouse-refresh').disabled=true;$('#warehouse-status').textContent='正在读取持久快照…';
  try{const v=await api('/api/data/catalog'+(cursor?'?cursor='+encodeURIComponent(cursor):''));warehouseEntries=v.entries;warehouseCursor=v.cursor;$('#warehouse-next').hidden=!v.truncated;$('#warehouse-status').textContent=warehouseEntries.length?`本页 ${warehouseEntries.length} 个不可变快照${v.truncated?' · 尚有更多页':''} · 采集时间为数据源同步时间，不代表已启用定时任务。`:'仓库尚无数据。导入 JSON 数据包后会持久保存。';$('#warehouse-list').innerHTML=warehouseEntries.length?'<table><thead><tr><th>证券 / 来源</th><th>实际覆盖</th><th>完整性</th><th>入库时间</th><th>操作</th></tr></thead><tbody>'+warehouseEntries.map((x,i)=>`<tr><td>${esc(x.symbol)} · ${esc(boardNames[x.board]||'待补')}<br>${esc(x.source)} · ${esc(x.timeframe)}<br><small>SHA-256 ${x.id.slice(0,12)}</small></td><td>${esc(x.report.actual.from||'无')}<br>${esc(x.report.actual.to||'无')}<br>${num(x.report.actual.bars,0)} 根</td><td class="quality-${x.report.status}">${esc(x.report.label)}<br>${x.report.issues.length} 类问题</td><td>${esc(new Date(x.syncedAt).toLocaleString('zh-CN',{hour12:false}))}</td><td><div class="warehouse-actions"><button class="load-params" data-bundle="${i}">载入 / 查看缺口</button><button class="text-button" data-snapshot="${i}">下载快照</button></div></td></tr>`).join('')+'</tbody></table>':'';
    $$('[data-bundle]').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;try{const x=warehouseEntries[Number(btn.dataset.bundle)],b=await api('/api/data/bundle?id='+x.id);await loadBundle(b,x.symbol,false,x.id);}catch(e){toast(e.message);}finally{btn.disabled=false;}});
    $$('[data-snapshot]').forEach(btn=>btn.onclick=async()=>{try{const x=warehouseEntries[Number(btn.dataset.snapshot)],a=document.createElement('a');a.href='/api/data/bundle?id='+x.id;a.download=x.symbol+'-'+x.id.slice(0,12)+'.json';a.click();}catch(e){toast(e.message);}});
  }catch(e){$('#warehouse-status').textContent=e.message;}finally{$('#warehouse-refresh').disabled=false;}
}
